    private void applyDebitSkinCard(String missionKey, String description, String instruction, String requirements) {
        String key = "quest.debitskin.v3." + missionKey;   // v3: траты названы в рублях; v2 (26.11.2026): тексты сверены с условиями офферов и тем, как бот ведёт игрока
        try {
            if (appSettingRepository.findById(key).isPresent()) return;
            ru.gamebot.platform.service.PartnerMission pm = missionByKey(missionKey);
            Quest q = questRepository.findFirstByTitleAndGameName(pm.questTitle(), pm.gameName()).orElse(null);
            if (q == null) return;
            q.setDescription(description);
            q.setInstruction(instruction);
            q.setRequirements(requirements);
            questRepository.save(q);
            saveSetting(key);
            markSkinSwitch(missionKey);
            log.info("[QuestSeeder] Skin reward card applied: {}", missionKey);
        } catch (Exception e) {
            log.warn("[QuestSeeder] Skin card failed: {}", missionKey, e);
        }
    }

    private void markSkinSwitch(String missionKey) {
        String key = ru.gamebot.platform.service.QuestSkinService.SWITCH_KEY_PREFIX + missionKey;
        if (appSettingRepository.findById(key).isEmpty()) saveSetting(key);
    }

    /** 26.11.2026 (владелец): «если писать, сколько партнёр выводит деньги, никто не будет выполнять квест, про срок не пишем нигде».
     *  Вырезает из карточек квестов только сроки проверки и выплаты партнёром; сроки на действия самого игрока (купить в течение 30 дней) остаются. Повторный запуск ничего не меняет. */
    private void stripPartnerTerms() {
        try {
            int changed = 0;
            for (Quest q : questRepository.findAll()) {
                String d = withoutPartnerTerms(q.getDescription());
                String i = withoutPartnerTerms(q.getInstruction());
                String r = withoutPartnerTerms(q.getRequirements());
                // 27.11.2026 (владелец): в игровых квестах с переходом на лендинг строку «Реклама · erid» убираем (маркировка на лендинге); мини-апп показывает этот же текст
                if (r != null && "landing".equals(q.getExternalNetwork())) r = r.replaceAll("(?m)\\n*^Реклама[^\\n]*$", "").trim();
                if (java.util.Objects.equals(d, q.getDescription()) && java.util.Objects.equals(i, q.getInstruction())
                        && java.util.Objects.equals(r, q.getRequirements())) continue;
                q.setDescription(d);
                q.setInstruction(i);
                q.setRequirements(r);
                questRepository.save(q);
                changed++;
            }
            if (changed > 0) log.info("[QuestSeeder] Partner terms removed from {} quest cards", changed);
        } catch (Exception e) {
            log.warn("[QuestSeeder] Partner terms cleanup failed", e);
        }
    }

    private static String withoutPartnerTerms(String text) {
        if (text == null) return null;
        return text
                .replaceAll("(?m)^⏳ (?:Подтверждение от партнёра|Партнёр )[^\n]*$", "💰 Рубли начислим в EXCASH, они выводятся без лимитов.")
                .replaceAll("(Банк подтверждает (?:карту|выдачу карты))(?: обычно)? в течение \\d+ дней", "$1")
                .replaceAll("(Банк (?:вернёт|отправит|начислит)[^.\n]*?)(?: обычно)? в течение \\d+ дней(?:, максимум \\d+)?", "$1")
                .replaceAll("(Подтверждение приходит от партнёра автоматически),? ?(?:— )?обычно[^.\n]*\\.", "$1.")
                .replace(" (обычно до 60 дней)", "")
                .replace(" Проверка занимает до 30–60 дней — это нормально, просто дождитесь.", "");
    }

    private void saveSetting(String key) {
        ru.gamebot.platform.domain.model.AppSetting a = new ru.gamebot.platform.domain.model.AppSetting();
        a.setKey(key);
        a.setValue(LocalDateTime.now().toString());
        appSettingRepository.save(a);
    }

    /** 26.11.2026 (владелец): квест «Т-Банк приведи друга» скрыт - у реферальной ссылки банка нет постбека, а карту Black закрывает квест LeadGid «Т-Банк Black».
     *  Один раз (ключ app_settings): включённый потом вручную квест сидер не трогает. */
    private void hideTblackReferralQuest() {
        String key = "quest.tblack.referral.hidden.v1";
        try {
            if (appSettingRepository.findById(key).isPresent()) return;
            ru.gamebot.platform.service.PartnerMission pm = missionByKey("tblack");
            Quest q = questRepository.findFirstByTitleAndGameName(pm.questTitle(), pm.gameName()).orElse(null);
            if (q == null) return;
            long open = questSubmissionRepository.findActiveByQuest(q).size();
            q.setActive(false);
            questRepository.save(q);
            saveSetting(key);
            log.info("[QuestSeeder] Hidden T-Bank referral quest, open submissions: {}", open);
        } catch (Exception e) {
            log.warn("[QuestSeeder] Hiding T-Bank referral quest failed", e);
        }
    }

    private void enableGameOfferOnce(String title, String gameName, String key) {
        if (appSettingRepository.findById(key).isPresent()) return;
        Quest q = questRepository.findFirstByTitleAndGameName(title, gameName).orElse(null);
        if (q == null) {
            log.warn("[QuestSeeder] Cannot enable game offer quest, not found: {}", gameName);
            return;
        }
        q.setActive(true);
        questRepository.save(q);
        saveSetting(key);
        log.info("[QuestSeeder] Game offer quest enabled: {}", gameName);
    }

