    /** Тексты квеста «ОТП Карта». Инструкция - блоки через пустую строку (первая строка блока = короткий заголовок шага с акцентом на выгоду): на карточке под баннером
     *  показываются только заголовки (подпись фото до 1024 символов), а после «Взять» бот присылает подробную инструкцию, каждый шаг отдельной цитатой.
     *  В «условиях» - блок «Условия», на карточке он в свёрнутой цитате. */
    private void applyOtpCardContent(Quest q) {
        q.setTitle(OTP_CARD_TITLE);
        q.setModeratorChecklist(OTP_CARD_CHECKLIST);
        // 26.11.2026 (владелец): карточка в формате остальных дебетовых квестов. Строку про курс партнёра бот добавляет последней в списке (процент считается из настроек)
        q.setDescription("Что ты получаешь:\n"
                + "✅ 1 000 ₽ от банка за покупку картой от 100 ₽\n"
                + skinLines("AWP | Mortis (Field-Tested)", 400)
                + SKIN_PRIVACY);
        q.setInstruction(skinSteps("1️⃣ Оформи заявку на бесплатную карту онлайн", "Получи карту курьером и за 30 дней купи от 100 ₽", "Получи 1 000 ₽ от банка и скин в Steam")); // шаблон владельца 20.11.2026, сверено с оффером 26.11.2026
        q.setRequirements("ℹ️ Кому подходит\n"
                + "18+, паспорт РФ, живёшь в России (кроме Крыма, ДНР, ЛНР), 2 года не было продуктов ОТП Банка. Карту бери курьером: из офиса не засчитают. "
                + "Заявку подавай без VPN. Скин даёт клуб, для него нужна ссылка обмена Steam.");
    }

    /** Разовое обновление текста уже созданного квеста ОТП (ключ app_settings): дальше правки из админки не затираются. */
    private void applyOtpUnifiedCard() {
        String key = "quest.otp.card.unified.v1";
        try {
            if (appSettingRepository.findById(key).isPresent()) return;
            Quest q = questRepository.findFirstByTitleAndGameName(OTP_CARD_TITLE, OTP_GAME).orElse(null);
            if (q == null) return;
            applyOtpCardContent(q);
            questRepository.save(q);
            saveSetting(key);
            log.info("[QuestSeeder] OTP card unified with other debit cards");
        } catch (Exception e) {
            log.warn("[QuestSeeder] OTP card unify failed", e);
        }
    }

    /**
     * Помечает уже существующий квест одноразовым для аккаунта — награда начисляется один раз навсегда,
     * повторное взятие после одобрения блокируется (QuestService.takeQuestChecked, тот же путь, что и у
     * externalAutoApprove). Идемпотентен — вызывается на каждом деплое.
     */
    private void markOneTimePerAccount(String title, String gameName) {
        questRepository.findFirstByTitleAndGameName(title, gameName)
                .filter(q -> !q.isOneTimePerAccount())
                .ifPresent(q -> {
                    q.setOneTimePerAccount(true);
                    questRepository.save(q);
                    log.info("[QuestSeeder] Marked one-time-per-account: '{}' ({})", title, gameName);
                });
    }

    /** Снимает ранее выставленный oneTimePerAccount — для квестов, которые перешли на настоящую API-верификацию. */
    private void clearOneTimePerAccount(String title, String gameName) {
        questRepository.findFirstByTitleAndGameName(title, gameName)
                .filter(Quest::isOneTimePerAccount)
                .ifPresent(q -> {
                    q.setOneTimePerAccount(false);
                    questRepository.save(q);
                    log.info("[QuestSeeder] Cleared one-time-per-account (superseded by API verification): '{}' ({})", title, gameName);
                });
    }

    /**
     * Пилот "квесты без стен" (2026-09-15): снимает кулдаун (оба вида) и лимит участников с уже существующего
     * квеста, взамен включает кривую убывания награды внутри окна (см. QuestService.computeReward). Идемпотентен —
     * вызывается на каждом деплое; baseRewardBeforeChange фиксируется один раз при первом включении флага.
     */
    private void markRepeatableNoCooldown(String title, String gameName, long targetPeriodCeiling, RewardDecayWindow window) {
        questRepository.findFirstByTitleAndGameName(title, gameName).ifPresent(q -> {
            q.setRepeatableNoCooldownEligible(true);
            q.setParticipantLimit(null);
            q.setTargetPeriodCeiling(targetPeriodCeiling);
            q.setRewardDecayWindow(window);
            if (q.getBaseRewardBeforeChange() == null) {
                q.setBaseRewardBeforeChange(q.getRewardCoins());
            }
            questRepository.save(q);
            log.info("[QuestSeeder] Marked repeatable-no-cooldown: '{}' ({}), ceiling={}, window={}", title, gameName, targetPeriodCeiling, window);
        });
    }

    /** Откатывает markRepeatableNoCooldown — возвращает квест к обычному поведению (кулдаун снова
     *  действует, кривая убывания больше не применяется). Идемпотентен, вызывается на каждом деплое —
     *  если квест уже не помечен, ничего не делает. Использовано 2026-09-20: вторая волна пилота
     *  (CS2/Clash Royale/PUBG PC, см. project_no_cooldown_quest_pilot) отключена по решению пользователя
     *  — увеличивать эмиссию EXC на обычных (не спонсорских) квестах без встречной монетизации активности
     *  не имеет смысла; пилот на Brawl Stars НЕ трогаем, остаётся как было с 2026-09-15. */
    private void clearRepeatableNoCooldown(String title, String gameName) {
        questRepository.findFirstByTitleAndGameName(title, gameName)
                .filter(Quest::isRepeatableNoCooldownEligible)
                .ifPresent(q -> {
                    q.setRepeatableNoCooldownEligible(false);
                    q.setTargetPeriodCeiling(null);
                    q.setRewardDecayWindow(null);
                    questRepository.save(q);
                    log.info("[QuestSeeder] Cleared repeatable-no-cooldown: '{}' ({})", title, gameName);
                });
    }

    /**
     * Проставляет структурные данные авто-верификации Clash of Clans квесту, уже созданному через seed()/updateQuest().
     * Идемпотентен — вызывается на каждом деплое. Игра всегда "Clash of Clans" — единственная, где сейчас есть эта авто-верификация.
     */
    private void setClashVerify(String title, ClashVerifyType type, int targetCount,
                                 String description, String instruction, String requirements) {
        questRepository.findFirstByTitleAndGameName(title, "Clash of Clans").ifPresentOrElse(q -> {
            q.setClashVerifyType(type);
            q.setClashTargetCount(targetCount);
            q.setDescription(description);
            q.setInstruction(instruction);
            q.setRequirements(requirements);
            // см. оговорку у setBrawlVerify — seed() не реактивирует случайно выключенную строку.
            q.setActive(true);
            questRepository.save(q);
        }, () -> log.warn("[QuestSeeder] setClashVerify: quest not found (seed must run first): '{}'", title));
    }

    /**
     * Проставляет структурные данные авто-верификации Clash Royale квесту, уже созданному через seed()/updateQuest().
     * Идемпотентен — вызывается на каждом деплое.
     */
    private void setClashRoyaleVerify(String title, ClashRoyaleVerifyType type, int targetCount,
                                       String description, String instruction, String requirements) {
        questRepository.findFirstByTitleAndGameName(title, "Clash Royale").ifPresentOrElse(q -> {
            q.setClashRoyaleVerifyType(type);
            q.setClashRoyaleTargetCount(targetCount);
            q.setDescription(description);
            q.setInstruction(instruction);
            q.setRequirements(requirements);
            // см. оговорку у setBrawlVerify — seed() не реактивирует случайно выключенную строку.
            // Это и был реальный баг: "Победи 20 раз в Клановых войнах за сезон" был active=false
            // (скорее всего случайно выключен в админке до этой сессии), seed()/этот метод его не
            // включали обратно — квест существовал и верифицировался, но не показывался игрокам.
            q.setActive(true);
            questRepository.save(q);
        }, () -> log.warn("[QuestSeeder] setClashRoyaleVerify: quest not found (seed must run first): '{}'", title));
    }

    /** Квесты, которыми управляет сидер: без спонсорских. У спонсорского квеста «Подпишись на канал» gameName = название канала спонсора, и оно может
     *  совпасть с названием игры БЕЗ учёта регистра («BRAWL STARS» == «Brawl Stars»): тогда очистки «деактивировать/удалить всё, чего нет в keep-списке»
     *  гасили такой квест при каждом старте бота (2026-10-10: у игроков «Квест закрыт», хотя кампания жива). Сидер спонсорские квесты не создаёт и не трогает. */
    private List<Quest> seederQuests() {
        return questRepository.findAll().stream()
                .filter(q -> q.getSponsorId() == null && !q.isSponsored())
                .toList();
    }

    private void deactivateGame(String gameName) {
        seederQuests().stream()
                .filter(q -> gameName.equalsIgnoreCase(q.getGameName()) && q.isActive())
                .forEach(q -> {
                    q.setActive(false);
                    questRepository.save(q);
                    log.info("[QuestSeeder] Closed access (deactivated): '{}' [{}]", q.getTitle(), gameName);
                });
    }

    /** Форсит category=null и фиксированную награду на каждом деплое — для игр, переведённых в FLAT-режим
     *  после того как часть их квестов уже создана через seed()/updateQuest() (те category не трогают). */
    private void flattenQuest(String title, String gameName, long rewardCoins, int rewardXp) {
        questRepository.findFirstByTitleAndGameName(title, gameName).ifPresent(q -> {
            q.setCategory(null);
            q.setRewardCoins(rewardCoins);
            q.setRewardXp(rewardXp);
            questRepository.save(q);
        });
    }

    /** Как deactivateGame, но точечно по названиям — форсит active=false на каждом деплое независимо
     *  от keepXxxTitles/seedFlat, переживает случайный ручной "включить" в админке. */
    private void deactivateQuests(String gameName, Set<String> titles) {
        seederQuests().stream()
                .filter(q -> gameName.equalsIgnoreCase(q.getGameName()) && titles.contains(q.getTitle()) && q.isActive())
                .forEach(q -> {
                    q.setActive(false);
                    questRepository.save(q);
                    log.info("[QuestSeeder] Closed access (deactivated): '{}' [{}]", q.getTitle(), gameName);
                });
    }

    private void seedFlat(String title, String gameName, String platform,
                         int durationDays, String durationText,
                         long rewardXp, long rewardCoins,
                         String description, String instruction, String requirements) {
        var existing = questRepository.findFirstByTitleAndGameName(title, gameName);
        if (existing.isPresent()) {
            Quest q = existing.get();
            q.setCategory(null);
            q.setPlatform(platform);
            q.setDurationDays(durationDays);
            q.setDurationText(durationText);
            q.setRewardXp(rewardXp);
            q.setRewardCoins(rewardCoins);
            q.setDescription(description);
            q.setInstruction(instruction);
            q.setRequirements(requirements);
            questRepository.save(q);
            log.info("[QuestSeeder] Updated to FLAT: '{}'", title);
            return;
        }
        Quest quest = new Quest();
        quest.setTitle(title);
        quest.setGameName(gameName);
        quest.setCategory(null);
        quest.setPlatform(platform);
        quest.setDurationDays(durationDays);
        quest.setDurationText(durationText);
        quest.setRewardXp(rewardXp);
        quest.setRewardCoins(rewardCoins);
        quest.setDescription(description);
        quest.setInstruction(instruction);
        quest.setRequirements(requirements);
        quest.setActive(true);
        quest.setCouncilOnly(false);
        quest.setCreatedAt(LocalDateTime.now());
        questRepository.save(quest);
        log.info("[QuestSeeder] Created FLAT: '{}'", title);
    }

    private void seed(String title, String gameName, String category, String platform,
                      int durationDays, String durationText,
                      long rewardXp, long rewardCoins,
                      String description, String instruction, String requirements) {
        var existing = questRepository.findFirstByTitleAndGameName(title, gameName);
        if (existing.isPresent()) {
            log.info("[QuestSeeder] Already exists, skipping: '{}'", title);
            return;
        }
        Quest quest = new Quest();
        quest.setTitle(title);
        quest.setGameName(gameName);
        quest.setCategory(category);
        quest.setPlatform(platform);
        quest.setDurationDays(durationDays);
        quest.setDurationText(durationText);
        quest.setRewardXp(rewardXp);
        quest.setRewardCoins(rewardCoins);
        quest.setDescription(description);
        quest.setInstruction(instruction);
        quest.setRequirements(requirements);
        quest.setActive(true);
        quest.setCouncilOnly(false);
        quest.setCreatedAt(LocalDateTime.now());
        questRepository.save(quest);
        log.info("[QuestSeeder] Created: '{}'", title);
    }

    // One-time migration: renames and fully replaces content when found under oldTitle.
    // On subsequent runs (quest already has newTitle), only updates rewards — like seed().
    private void updateQuest(String oldTitle, String gameName,
                             String newTitle, String category, String platform,
                             int durationDays, String durationText,
                             long rewardXp, long rewardCoins,
                             String description, String instruction, String requirements) {
        var byOldTitle = questRepository.findFirstByTitleAndGameName(oldTitle, gameName);
        if (byOldTitle.isPresent()) {
            // One-time migration: apply full update
            Quest q = byOldTitle.get();
            q.setTitle(newTitle);
            q.setCategory(category);
            q.setPlatform(platform);
            q.setDurationDays(durationDays);
            q.setDurationText(durationText);
            q.setRewardXp(rewardXp);
            q.setRewardCoins(rewardCoins);
            q.setDescription(description);
            q.setInstruction(instruction);
            q.setRequirements(requirements);
            // Реактивируем: keepBsTitles-очистка выше в этом же прогоне видит ещё СТАРЫЙ title
            // (переименование ещё не произошло) и деактивирует запись как "не из списка" —
            // без этого переименованный квест навсегда остаётся active=false после первого деплоя.
            // Срабатывает только один раз (при следующем запуске пойдёт в ветку byNewTitle ниже),
            // так что не наступает на уже исправленный ранее баг "seedFlat каждый раз включает квест".
            q.setActive(true);
            questRepository.save(q);
            log.info("[QuestSeeder] Full update: '{}' -> '{}'", oldTitle, newTitle);
            return;
        }
        // Quest already has newTitle (migration already done) — only update rewards
        var byNewTitle = questRepository.findFirstByTitleAndGameName(newTitle, gameName);
        if (byNewTitle.isPresent()) {
            Quest q = byNewTitle.get();
            q.setRewardXp(rewardXp);
            q.setRewardCoins(rewardCoins);
            questRepository.save(q);
            log.info("[QuestSeeder] Updated rewards: '{}'", newTitle);
            return;
        }
        // Neither found — create fresh
        seed(newTitle, gameName, category, platform, durationDays, durationText,
                rewardXp, rewardCoins, description, instruction, requirements);
    }

    /**
     * Проставляет структурные данные авто-верификации Brawl Stars квесту, уже созданному через seedFlat().
     * Идемпотентен — вызывается на каждом деплое, просто перезаписывает поля. Отдельный метод (не параметр
     * seedFlat) — seedFlat переиспользуется квестами многих игр и не должен обрастать Brawl-специфичными
     * параметрами.
     */
    private void setBrawlVerify(String title, BrawlVerifyType type, int targetCount,
                                 boolean requireVictory, boolean requireRanked, boolean requireTeam,
                                 String modeKeys, String brawlerNames) {
        questRepository.findFirstByTitleAndGameName(title, "Brawl Stars").ifPresentOrElse(q -> {
            q.setBrawlVerifyType(type);
            q.setBrawlTargetCount(targetCount);
            q.setBrawlRequireVictory(requireVictory);
            q.setBrawlRequireRanked(requireRanked);
            q.setBrawlRequireTeam(requireTeam);
            q.setBrawlModeKeys(modeKeys);
            q.setBrawlBrawlerNames(brawlerNames);
            // seed()/seedFlat() не реактивируют уже существующую (случайно выключенную) строку —
            // раз мы явно настраиваем авто-верификацию, квест точно должен быть виден игрокам
            // (инцидент 2026-08-31: "Победи 20 раз в Клановых войнах за сезон" молча оказался active=false).
            q.setActive(true);
            questRepository.save(q);
        }, () -> log.warn("[QuestSeeder] setBrawlVerify: quest not found (seedFlat must run first): '{}'", title));
    }

    /**
     * Проставляет авто-верификацию Dota 2 (Steam Web API) уже существующему ручному квесту (retrofit,
     * не создание новых квестов — все 12 квестов Dota давно есть в seed() ниже). В отличие от setBrawlVerify
     * нет параметров-фильтров по герою/режиму/победе — ни один из 12 квестов Dota их не требует
     * ("любой герой", "любой режим", "победа или поражение не важны"). Идемпотентен, вызывается на каждом деплое.
     */
    private void setDotaVerify(String title, DotaVerifyType type, int targetCount) {
        questRepository.findFirstByTitleAndGameName(title, "Dota 2").ifPresentOrElse(q -> {
            q.setDotaVerifyType(type);
            q.setDotaTargetCount(targetCount);
            // см. оговорку у setBrawlVerify — seed() не реактивирует случайно выключенную строку.
            q.setActive(true);
            questRepository.save(q);
        }, () -> log.warn("[QuestSeeder] setDotaVerify: quest not found (seed must run first): '{}'", title));
    }

